FILES = {'dbt_project.yml': 'name: "f1"\nversion: "1.0.0"\nconfig-version: 2\n\nprofile: "motherduck"\n\nmodel-paths: ["models"]\nclean-targets: ["target", "dbt_packages"]\n\nmodels:\n  f1:\n    staging:\n      +materialized: view\n      +schema: staging\n    marts:\n      +materialized: table\n      +schema: marts\n', 'macros/generate_schema_name.sql': '{#\n  dbt\'s default behavior concatenates the target schema with any custom\n  +schema config (e.g. "main_marts"). We want the custom schema name used\n  as-is (e.g. "marts"), so models land in f1.marts / f1.staging.\n#}\n{% macro generate_schema_name(custom_schema_name, node) -%}\n    {%- if custom_schema_name is none -%}\n        {{ target.schema }}\n    {%- else -%}\n        {{ custom_schema_name | trim }}\n    {%- endif -%}\n{%- endmacro %}\n', 'models/marts/dim_drivers.sql': "-- Team/name info rarely changes intra-season; collapse to one row per\n-- driver by taking their most recent session's record.\nwith drivers as (\n    select\n        d.*,\n        s.date_start as session_date_start,\n        row_number() over (\n            partition by d.driver_number\n            order by s.date_start desc\n        ) as rn\n    from {{ ref('stg_openf1__drivers') }} d\n    left join {{ ref('stg_openf1__sessions') }} s on d.session_key = s.session_key\n)\n\nselect\n    driver_number,\n    full_name,\n    broadcast_name,\n    name_acronym,\n    team_name,\n    team_colour\nfrom drivers\nwhere rn = 1\n", 'models/marts/dim_radio_topics.sql': "select\n    topic_id,\n    label as topic_label,\n    top_keywords,\n    doc_count\nfrom {{ ref('stg_radio__topics') }}\n", 'models/marts/dim_sessions.sql': "with sessions as (\n    select * from {{ ref('stg_openf1__sessions') }}\n),\n\nmeetings as (\n    select * from {{ ref('stg_openf1__meetings') }}\n)\n\nselect\n    s.session_key,\n    s.meeting_key,\n    m.year,\n    m.country_name,\n    m.circuit_short_name,\n    m.meeting_official_name,\n    s.session_name,\n    s.date_start,\n    s.date_end\nfrom sessions s\nleft join meetings m on s.meeting_key = m.meeting_key\n", 'models/marts/fct_driver_topic_race.sql': "-- Driver x session x topic grain: how many radio messages of each topic a\n-- driver had in a given race, and what share of that driver's radio traffic\n-- that topic made up. This is the grain the season-evolution Dive charts\n-- (topic mix per driver/team across races) query directly.\nwith messages as (\n    select * from {{ ref('fct_radio_messages') }}\n),\n\ncounts as (\n    select\n        session_key,\n        year,\n        country_name,\n        circuit_short_name,\n        meeting_official_name,\n        session_date,\n        driver_number,\n        driver_full_name,\n        driver_acronym,\n        team_name,\n        team_colour,\n        topic_id,\n        topic_label,\n        count(*) as message_count\n    from messages\n    group by all\n),\n\ndriver_totals as (\n    select\n        session_key,\n        driver_number,\n        sum(message_count) as driver_total_messages\n    from counts\n    group by all\n)\n\nselect\n    c.session_key,\n    c.year,\n    c.country_name,\n    c.circuit_short_name,\n    c.meeting_official_name,\n    c.session_date,\n    c.driver_number,\n    c.driver_full_name,\n    c.driver_acronym,\n    c.team_name,\n    c.team_colour,\n    c.topic_id,\n    c.topic_label,\n    c.message_count,\n    dt.driver_total_messages,\n    c.message_count / dt.driver_total_messages as share_of_driver_messages\nfrom counts c\njoin driver_totals dt\n    on c.session_key = dt.session_key\n    and c.driver_number = dt.driver_number\n", 'models/marts/fct_lap_pace.sql': "-- Core mart for relative pace analysis: each driver's lap time compared to\n-- the fastest and median lap turned by the whole field on that same lap of\n-- that same session, so drivers are compared under identical track/weather\n-- conditions rather than across the whole race distance.\nwith laps as (\n    select * from {{ ref('fct_laps') }}\n),\n\nlap_stats as (\n    select\n        session_key,\n        lap_number,\n        min(lap_duration) as fastest_lap_duration,\n        median(lap_duration) as median_lap_duration\n    from laps\n    group by 1, 2\n)\n\nselect\n    l.session_key,\n    se.meeting_key,\n    se.year,\n    se.country_name,\n    se.circuit_short_name,\n    se.meeting_official_name,\n    se.date_start as session_date,\n    l.driver_number,\n    d.full_name as driver_full_name,\n    d.name_acronym as driver_acronym,\n    d.team_name,\n    d.team_colour,\n    l.lap_number,\n    l.lap_duration,\n    ls.fastest_lap_duration,\n    ls.median_lap_duration,\n    l.lap_duration - ls.fastest_lap_duration as delta_to_fastest,\n    l.lap_duration - ls.median_lap_duration as delta_to_median,\n    rank() over (\n        partition by l.session_key, l.lap_number\n        order by l.lap_duration asc\n    ) as lap_rank\nfrom laps l\njoin lap_stats ls\n    on l.session_key = ls.session_key\n    and l.lap_number = ls.lap_number\nleft join {{ ref('dim_sessions') }} se on l.session_key = se.session_key\nleft join {{ ref('dim_drivers') }} d on l.driver_number = d.driver_number\n", 'models/marts/fct_laps.sql': "-- Excludes pit-out laps and null/zero durations, which aren't representative\n-- of green-flag race pace and would distort relative-pace comparisons.\nselect\n    session_key,\n    driver_number,\n    lap_number,\n    date_start,\n    lap_duration,\n    duration_sector_1,\n    duration_sector_2,\n    duration_sector_3,\n    i1_speed,\n    i2_speed,\n    st_speed\nfrom {{ ref('stg_openf1__laps') }}\nwhere coalesce(is_pit_out_lap, false) = false\n  and lap_duration is not null\n  and lap_duration > 0\n", 'models/marts/fct_radio_messages.sql': "-- Each radio message tagged with the lap in progress when it was sent (the\n-- last lap that had already started as of message_date), plus driver/session\n-- dims and its BERTopic topic, so a message can be placed on both the lap\n-- timeline of a race and the topic timeline of a season.\nwith messages as (\n    select * from {{ ref('stg_radio__messages') }}\n),\n\nlaps as (\n    select * from {{ ref('fct_laps') }}\n),\n\nsessions as (\n    select * from {{ ref('dim_sessions') }}\n),\n\ndrivers as (\n    select * from {{ ref('dim_drivers') }}\n),\n\ntopics as (\n    select * from {{ ref('dim_radio_topics') }}\n),\n\nmessage_laps as (\n    select\n        m.radio_message_id,\n        l.lap_number,\n        row_number() over (\n            partition by m.radio_message_id\n            order by l.date_start desc\n        ) as rn\n    from messages m\n    left join laps l\n        on m.session_key = l.session_key\n        and m.driver_number = l.driver_number\n        and l.date_start <= m.message_date\n)\n\nselect\n    m.radio_message_id,\n    m.session_key,\n    se.year,\n    se.country_name,\n    se.circuit_short_name,\n    se.meeting_official_name,\n    se.date_start as session_date,\n    m.driver_number,\n    d.full_name as driver_full_name,\n    d.name_acronym as driver_acronym,\n    d.team_name,\n    d.team_colour,\n    ml.lap_number,\n    m.message_date,\n    m.transcript_text,\n    m.language,\n    m.duration_sec,\n    m.topic_id,\n    coalesce(t.topic_label, 'Uncategorized') as topic_label,\n    t.top_keywords as topic_keywords\nfrom messages m\nleft join message_laps ml\n    on m.radio_message_id = ml.radio_message_id and ml.rn = 1\nleft join sessions se on m.session_key = se.session_key\nleft join drivers d on m.driver_number = d.driver_number\nleft join topics t on m.topic_id = t.topic_id\n", 'models/schema.yml': 'version: 2\n\nmodels:\n  - name: dim_sessions\n    columns:\n      - name: session_key\n        tests:\n          - unique\n          - not_null\n\n  - name: dim_drivers\n    columns:\n      - name: driver_number\n        tests:\n          - unique\n          - not_null\n\n  - name: fct_laps\n    columns:\n      - name: session_key\n        tests:\n          - not_null\n      - name: driver_number\n        tests:\n          - not_null\n      - name: lap_number\n        tests:\n          - not_null\n\n  - name: fct_lap_pace\n    columns:\n      - name: session_key\n        tests:\n          - not_null\n      - name: driver_number\n        tests:\n          - not_null\n\n  - name: dim_radio_topics\n    columns:\n      - name: topic_id\n        tests:\n          - unique\n          - not_null\n\n  - name: fct_radio_messages\n    columns:\n      - name: radio_message_id\n        tests:\n          - unique\n          - not_null\n      - name: session_key\n        tests:\n          - not_null\n      - name: driver_number\n        tests:\n          - not_null\n\n  - name: fct_driver_topic_race\n    columns:\n      - name: session_key\n        tests:\n          - not_null\n      - name: driver_number\n        tests:\n          - not_null\n      - name: topic_id\n        tests:\n          - not_null\n', 'models/sources.yml': 'version: 2\n\nsources:\n  - name: openf1\n    database: f1\n    schema: raw\n    tables:\n      - name: meetings\n      - name: sessions\n      - name: drivers\n      - name: laps\n\n  - name: radio\n    description: >\n      Populated by spark_jobs/radio_topic_modeling/job.py (Whisper transcription +\n      BERTopic topic modeling), written as Iceberg tables and attached into\n      MotherDuck via warehouse/setup_radio_lakehouse.sql. Not populated by any\n      Flight in this repo.\n    database: radio_lakehouse\n    schema: raw\n    tables:\n      - name: radio_messages\n      - name: radio_topics\n', 'models/staging/stg_openf1__drivers.sql': "with source as (\n    select * from {{ source('openf1', 'drivers') }}\n)\n\nselect\n    session_key,\n    driver_number,\n    full_name,\n    broadcast_name,\n    name_acronym,\n    team_name,\n    team_colour\nfrom source\n", 'models/staging/stg_openf1__laps.sql': "with source as (\n    select * from {{ source('openf1', 'laps') }}\n)\n\nselect\n    session_key,\n    driver_number,\n    lap_number,\n    cast(date_start as timestamptz) as date_start,\n    lap_duration,\n    duration_sector_1,\n    duration_sector_2,\n    duration_sector_3,\n    i1_speed,\n    i2_speed,\n    st_speed,\n    is_pit_out_lap\nfrom source\n", 'models/staging/stg_openf1__meetings.sql': "with source as (\n    select * from {{ source('openf1', 'meetings') }}\n)\n\nselect\n    meeting_key,\n    year,\n    country_name,\n    circuit_short_name,\n    meeting_official_name,\n    meeting_name,\n    location,\n    cast(date_start as timestamptz) as date_start,\n    cast(date_end as timestamptz) as date_end\nfrom source\n", 'models/staging/stg_openf1__sessions.sql': "with source as (\n    select * from {{ source('openf1', 'sessions') }}\n)\n\nselect\n    session_key,\n    meeting_key,\n    session_name,\n    session_type,\n    year,\n    cast(date_start as timestamptz) as date_start,\n    cast(date_end as timestamptz) as date_end\nfrom source\n", 'models/staging/stg_radio__messages.sql': "with source as (\n    select * from {{ source('radio', 'radio_messages') }}\n)\n\nselect\n    radio_message_id,\n    session_key,\n    meeting_key,\n    driver_number,\n    cast(message_date as timestamptz) as message_date,\n    transcript_text,\n    language,\n    duration_sec,\n    topic_id\nfrom source\nwhere transcribe_error is null\n  and transcript_text is not null\n", 'models/staging/stg_radio__topics.sql': "with source as (\n    select * from {{ source('radio', 'radio_topics') }}\n)\n\nselect\n    topic_id,\n    label,\n    top_keywords,\n    doc_count\nfrom source\n-- BERTopic reserves topic_id = -1 for outlier/unclustered messages; keep it\n-- out of dim_radio_topics since it isn't a real topic, but stg_radio__messages\n-- still carries topic_id = -1 through so those messages aren't dropped.\nwhere topic_id != -1\n", 'profiles.yml': 'motherduck:\n  target: prod\n  outputs:\n    prod:\n      type: duckdb\n      path: "md:f1?motherduck_token={{ env_var(\'MOTHERDUCK_TOKEN\') }}"\n      threads: 4\n', 'tests/assert_fct_driver_topic_race_unique_grain.sql': "-- fct_driver_topic_race should have exactly one row per session/driver/topic\nselect session_key, driver_number, topic_id, count(*) as n\nfrom {{ ref('fct_driver_topic_race') }}\ngroup by 1, 2, 3\nhaving count(*) > 1\n", 'tests/assert_fct_lap_pace_unique_grain.sql': "-- fct_lap_pace should have exactly one row per session/driver/lap\nselect session_key, driver_number, lap_number, count(*) as n\nfrom {{ ref('fct_lap_pace') }}\ngroup by 1, 2, 3\nhaving count(*) > 1\n", 'tests/assert_fct_laps_unique_grain.sql': "-- fct_laps should have exactly one row per session/driver/lap\nselect session_key, driver_number, lap_number, count(*) as n\nfrom {{ ref('fct_laps') }}\ngroup by 1, 2, 3\nhaving count(*) > 1\n"}


